import React, { useState, useEffect } from "react";
import {
  Container,
  Row,
  Col,
  Card,
  Table,
  Button,
  Form,
  InputGroup,
} from "react-bootstrap";
import axios from "axios";

const LECTURER = () => {
  const [courses, setCourses] = useState([]);
  const [modules, setModules] = useState([]);
  const [tasks, setTasks] = useState([]);
  const [search, setSearch] = useState("");

  // Form states
  const [taskName, setTaskName] = useState("");
  const [dueDate, setDueDate] = useState("");
  const [selectedModule, setSelectedModule] = useState("");

  useEffect(() => {
    fetchAssignedData();
    fetchTasks();
  }, []);

  // ✅ Fetch lecturer's assigned courses and modules
  const fetchAssignedData = () => {
    axios
      .get("https://localhost:7013/api/Lecturer/Assigned/1") // pass lecturerId
      .then((res) => {
        setCourses(res.data.courses || []);
        setModules(res.data.modules || []);
      })
      .catch((err) => console.error(err));
  };

  // ✅ Fetch lecturer tasks
  const fetchTasks = () => {
    axios
      .get("https://localhost:7013/api/Task/Lecturer/1") // pass lecturerId
      .then((res) => {
        setTasks(res.data || []);
      })
      .catch((err) => console.error(err));
  };

  // ✅ Add new task
  const handleAddTask = () => {
    if (!taskName || !dueDate || !selectedModule) {
      alert("Please complete all fields");
      return;
    }

    axios
      .post("https://localhost:7013/api/Task", {
        taskName: taskName,
        dueDate: dueDate,
        moduleId: selectedModule,
        lecturerId: 1, // replace with logged-in lecturerId
      })
      .then(() => {
        alert("Task created ✅");
        fetchTasks();
        setTaskName("");
        setDueDate("");
        setSelectedModule("");
      })
      .catch((err) => console.error(err));
  };

  return (
    <Container fluid className="p-4">
      {/* ✅ Big Heading */}
      <Row className="mb-4">
        <Col>
          <h1 className="text-center fw-bold display-4 text-success">
            Lecturer Dashboard
          </h1>
        </Col>
      </Row>

      <Row>
        <Col>
          <Card className="shadow mb-4">
            <Card.Header>
              <h3>Your Courses & Modules</h3>
            </Card.Header>
            <Card.Body>
              <Row>
                <Col>
                  <h5>Courses</h5>
                  <ul>
                    {courses.length > 0 ? (
                      courses.map((c, i) => <li key={i}>{c.name}</li>)
                    ) : (
                      <li>No courses assigned</li>
                    )}
                  </ul>
                </Col>
                <Col>
                  <h5>Modules</h5>
                  <ul>
                    {modules.length > 0 ? (
                      modules.map((m, i) => <li key={i}>{m.name}</li>)
                    ) : (
                      <li>No modules assigned</li>
                    )}
                  </ul>
                </Col>
              </Row>
            </Card.Body>
          </Card>

          {/* ✅ Create Task Section */}
          <Card className="shadow mb-4">
            <Card.Header>
              <h3>Create Task</h3>
            </Card.Header>
            <Card.Body>
              <Form className="mb-3">
                <Row>
                  <Col>
                    <Form.Control
                      type="text"
                      placeholder="Task Name"
                      value={taskName}
                      onChange={(e) => setTaskName(e.target.value)}
                    />
                  </Col>
                  <Col>
                    <Form.Control
                      type="date"
                      value={dueDate}
                      onChange={(e) => setDueDate(e.target.value)}
                    />
                  </Col>
                  <Col>
                    <Form.Select
                      value={selectedModule}
                      onChange={(e) => setSelectedModule(e.target.value)}
                    >
                      <option value="">Select Module</option>
                      {modules.map((m, i) => (
                        <option key={i} value={m.moduleId}>
                          {m.name}
                        </option>
                      ))}
                    </Form.Select>
                  </Col>
                  <Col>
                    <Button onClick={handleAddTask}>Add Task</Button>
                  </Col>
                </Row>
              </Form>
            </Card.Body>
          </Card>

          {/* ✅ Tasks Table */}
          <Card className="shadow">
            <Card.Header>
              <h3>Tasks</h3>
            </Card.Header>
            <Card.Body>
              <InputGroup className="mb-3">
                <Form.Control
                  placeholder="Search by task name"
                  value={search}
                  onChange={(e) => setSearch(e.target.value)}
                />
                <Button variant="primary">Search</Button>
              </InputGroup>

              <Table striped bordered hover>
                <thead>
                  <tr>
                    <th>#</th>
                    <th>Task Name</th>
                    <th>Due Date</th>
                    <th>Module</th>
                  </tr>
                </thead>
                <tbody>
                  {tasks.length > 0 ? (
                    tasks
                      .filter((t) =>
                        t.taskName.toLowerCase().includes(search.toLowerCase())
                      )
                      .map((t, i) => (
                        <tr key={i}>
                          <td>{t.taskId}</td>
                          <td>{t.taskName}</td>
                          <td>{new Date(t.dueDate).toLocaleDateString()}</td>
                          <td>{t.moduleName}</td>
                        </tr>
                      ))
                  ) : (
                    <tr>
                      <td colSpan="4" className="text-center">
                        No tasks created
                      </td>
                    </tr>
                  )}
                </tbody>
              </Table>
            </Card.Body>
          </Card>
        </Col>
      </Row>
      <Row className="mb-2">
        <Col className="text-end">
          <Button variant="outline-danger" size="sm">
            Logout
          </Button>
        </Col>
      </Row>
    </Container>
  );
};

export default LECTURER;
